public static boolean shouldShowGUPUI(FormRun _formRun, ModuleInventCustVend _custVendValue = ModuleInventCustVend::Cust, boolean _useDirectValue = false)
{
    boolean showGUPUI = false;

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ModuleInventCustVend moduleInventCustVend;
        if (_useDirectValue)
        {
            moduleInventCustVend = _custVendValue;
        }
        else
        {
            FormDataSource TAMRebateDeal_ds = _formRun.dataSource(tablestr(TAMRebateDeal));
            TAMRebateDeal  rebateDeal = TAMRebateDeal_ds.cursor();
            moduleInventCustVend = rebateDeal.ModuleInventCustVend;
        }
        showGUPUI = moduleInventCustVend == ModuleInventCustVend::Cust;
    }
    return showGUPUI;
}

public static void setUpGUPUIForRebateDealFormLinesPage(FormRun _formRun)
{
    TAMRebateTypeGUP rebateTypeGUP = TAMRebateDealGUPExtensionHelper::getRebateTypeGUP(_formRun);
    boolean isPrepaidLumpsum = rebateTypeGUP == TAMRebateTypeGUP::PrepaidLumpsum;       

    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateLine_RebateFrom)).enabled(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateLine_RebateLimit)).enabled(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateLine_RebateMethod)).enabled(!isPrepaidLumpsum);

    if (isPrepaidLumpsum)
    {
        FormDataSource TAMRebateLine_ds = _formRun.dataSource(tablestr(TAMRebateLine));
        TAMRebateLine_ds.object(fieldNum(TAMRebateLine, RebateMethod)).setValue(TAMRebateMethod::Fixed);
    }
}

public static void setUpGUPUIForRebateDealFormDetailPage(FormRun _formRun)
{
    boolean showGUPUI = TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(_formRun);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_AccountCode)).visible(!showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_AccountRelation)).visible(!showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_ItemCode)).visible(!showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_ItemRelation)).visible(!showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_VariantId)).visible(!showGUPUI);

    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDeal_Recipient)).visible(showGUPUI);
    FormDataSource TAMRebateDeal_ds = _formRun.dataSource(tablestr(TAMRebateDeal));
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateAgreementType)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PriceComponentCombination)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeGroupNameHeader)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeDetailsHeader)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeGroupNameLine)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_PricingAttributeDetailsLine)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_CombinationPriority)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTablePriceAttributeGroupEdit)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateTablePricingRulePreviewAll)).visible(showGUPUI);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, InventDimParmFixedAction)).visible(showGUPUI);

    FormDataSource TAMRebateTable_ds = _formRun.dataSource(tablestr(TAMRebateTable));
    TAMRebateTypeGUP rebateTypeGUP = TAMRebateDealGUPExtensionHelper::getRebateTypeGUP(_formRun);
    boolean isPrepaidLumpsum = rebateTypeGUP == TAMRebateTypeGUP::PrepaidLumpsum;
    boolean isTransactionBased = rebateTypeGUP == TAMRebateTypeGUP::TransactionBased;

    _formRun.design().controlName(formControlStr(TAMRebateDeal, DatesHeaderView_RebateFromDate)).enabled(!isPrepaidLumpsum && !isTransactionBased);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, DatesHeaderView_RebateToDate)).enabled(!isPrepaidLumpsum && !isTransactionBased);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, Setup_Category)).enabled(!isPrepaidLumpsum && !isTransactionBased);

    if (isPrepaidLumpsum || isTransactionBased)
    {
        _formRun.design().controlName(formControlStr(TAMRebateDeal, Setup_CalculationMethod)).enabled(false);
        TAMRebateTable_ds.object(fieldNum(TAMRebateTable, CalculationMethod)).setValue(TAMRebateCalcMethod::Stepped);
    }                  

    _formRun.design().controlName(formControlStr(TAMRebateDeal, Setup_MinimumAmount)).enabled(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebatePeriodId)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateStartingDayOfWeek)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateClaimPeriodId)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_ProcessPosting)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateGuaranteePer)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateGuaranteePaid)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateGuaranteeMinimum)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebatePeriodCode)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateClaimBy)).visible(!isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebatePeriodCodeLumpsum)).visible(isPrepaidLumpsum);
    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateClaimByLumpsum)).visible(isPrepaidLumpsum);

    _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateLine_Occurrences)).visible(isPrepaidLumpsum);
    if (TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateActive)).getValue() == NoYes::Yes)
    {
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateLine_Occurrences)).enabled(isPrepaidLumpsum);
    }
    _formRun.design().controlName(formControlStr(TAMRebateDeal, GUPRebateAmortizationScheduleDetail)).visible(isPrepaidLumpsum);
}

public static void setUpGUPUIForRebateDealNewDealForm(FormRun _formRun)
{
    ModuleInventCustVend custVendValue;
    custVendValue = str2Enum(custVendValue, _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_ModuleInventCustVend)).valueStr());
    boolean showGUPUI = TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(_formRun, custVendValue, true);
    FormDataSource TAMRebateDeal_ds = _formRun.dataSource(tablestr(TAMRebateDeal));
    if (showGUPUI)
    {
        TAMRebateReconciliation rebateReconciliation;
        rebateReconciliation = str2Enum(rebateReconciliation, _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateReconciliation)).valueStr());
        boolean currentRebateReconciliationIsDeal = rebateReconciliation == TAMRebateReconciliation::Deal;

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).visible(true);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).allowEdit(currentRebateReconciliationIsDeal);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).mandatory(currentRebateReconciliationIsDeal);

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebatePostingId)).allowEdit(true);

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).visible(true);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).allowEdit(currentRebateReconciliationIsDeal);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).mandatory(currentRebateReconciliationIsDeal);

        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateAgreementType)).visible(true);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_Recipient)).visible(true);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateCompanyId)).visible(true);

        TAMRebateType rebateType;
        rebateType = str2Enum(rebateType, _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateType)).valueStr());
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateTypeGUP)).visible(rebateType == TAMRebateType::Rebate);
    }
    else
    {
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateFromDate)).visible(false);
        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateToDate)).visible(false);

        TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, RebateAgreementType)).mandatory(false);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateAgreementType)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_Recipient)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateCompanyId)).visible(false);
        _formRun.design().controlName(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateTypeGUP)).visible(false);

        TAMRebateDeal  rebateDeal = TAMRebateDeal_ds.cursor();
        rebateDeal.RebatePostingId = '';
    }
}

public static void setUpGUPUIForRebateDealFormDeactiveButton(FormRun _formRun, TAMRebateDeal _rebateDeal)
{
    if (TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(_formRun, _rebateDeal.ModuleInventCustVend, true))
    {
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDealDeactivateGUP)).enabled(_rebateDeal.RebateActive == NoYes::Yes);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDealDeactivateGUP)).visible(true);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateDealDeactivate)).visible(false);

        //for lumpsum prepaid
        boolean rebateTypeGUPIsNotPrepaidLumpsum = _rebateDeal.RebateTypeGUP != TAMRebateTypeGUP::PrepaidLumpsum;
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateCreateTransProvision)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateCreateTransWriteOff)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebatePostProvision)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebatePostWriteOff)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateCreateTransProvisionTable)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebateCreateTransWriteOffTable)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebatePostProvisionTable)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
        _formRun.design().controlName(formControlStr(TAMRebateDeal, TAMRebatePostWriteOffTable)).enabled(rebateTypeGUPIsNotPrepaidLumpsum);
    }
}

public static void rebateAgreementLookupBasedOnCompany(FormControl _sender, str _rebateCompanyId)
{
    SysTableLookup          sysTableLookup;
    Query                   query;
    QueryBuildDataSource    queryBuildDataSourceView;

    query = new Query();

    if (_rebateCompanyId && CompanyInfo::findDataArea(_rebateCompanyId).RecId)
    {
        query.allowCrossCompany(true);
        query.addCompanyRange(_rebateCompanyId);
        sysTableLookup = SysTableLookup::newParameters(tableNum(GUPRebateAgreementType), _sender);
        queryBuildDataSourceView = query.addDataSource(tableNum(GUPRebateAgreementType));

        sysTableLookup.addLookupfield(fieldNum(GUPRebateAgreementType, TypeName));
        sysTableLookup.addLookupfield(fieldNum(GUPRebateAgreementType, Description));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
    else
    {
        checkFailed('@GlobalUnifiedPricing:GUPRebateCompanyIsNotValid');
    }
}

public static boolean hasMoreThanOneRebateLine(FormRun _formRun)
{
    TAMRebateLine rebateLine;
    TAMRebateDate rebateDate = _formRun.dataSource(tableStr(TAMRebateDate)).cursor();

    select count(RecId) from rebateLine
        join rebateDate
        where rebateLine.RefLineNum == rebateDate.LineNum
            && rebateLine.RebateId == rebateDate.RebateId;

    return rebateLine.RecId > 1;
}

public static TAMRebateTypeGUP getRebateTypeGUP(FormRun _formRun)
{
    return _formRun.dataSource(tablestr(TAMRebateDeal)).object(fieldNum(TAMRebateDeal, RebateTypeGUP)).getValue();
}
